import {reportTask,showTasks} from './task-center.js?v=folded-groups1';
export function initMediaImport(onUploaded){
 const prompted=new Set();let activeChoice=null;const pendingChoices=[];
 const choiceDialog=document.createElement('dialog');choiceDialog.className='photo-book-dialog';choiceDialog.innerHTML='<header><h3>音轨检查</h3><button class="small-button" data-later>稍后处理</button></header><p data-title></p><p>疑似含人声或其他乐器。是否先分离钢琴再转录？</p><footer><button class="small-button" data-choice="original">直接转录</button><button class="small-button" data-choice="separate">分离钢琴后转录</button></footer><p role="status"></p>';document.body.append(choiceDialog);
 const nextChoice=()=>{if(activeChoice||!pendingChoices.length)return;activeChoice=pendingChoices.shift();choiceDialog.querySelector('[data-title]').textContent=activeChoice.scoreTitle||'上传的音视频';choiceDialog.querySelector('header+p+p').textContent=String(activeChoice.detail||'').includes('尚未就绪')?'音轨检查模型尚未就绪。可直接转录，或稍后在任务中心处理。':'疑似含人声或其他乐器。是否先分离钢琴再转录？';choiceDialog.querySelector('[role=status]').textContent='';choiceDialog.showModal();};
 choiceDialog.querySelector('[data-later]').onclick=()=>choiceDialog.close();choiceDialog.addEventListener('close',()=>{activeChoice=null;nextChoice();});
 choiceDialog.querySelectorAll('[data-choice]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const response=await fetch('/api/media/choice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({digest:activeChoice.digest,choice:button.dataset.choice})});if(!response.ok)throw Error('提交失败，请在任务中心重试');choiceDialog.close();showTasks();}catch(error){choiceDialog.querySelector('[role=status]').textContent=error.message;}finally{button.disabled=false;}});
 document.addEventListener('cloud-jobs-update',event=>{for(const task of event.detail||[]){if(task.kind==='transcription'&&task.status==='needs_review'&&!prompted.has(task.id)){prompted.add(task.id);pendingChoices.push(task);}}nextChoice();});
 const taskId=prefix=>prefix+'-'+Date.now()+'-'+Math.random().toString(36).slice(2);
 const section=document.querySelector('.score-import'),actions=document.createElement('div');actions.className='media-import-actions';
 actions.innerHTML='<button class="small-button" type="button" data-photos>照片组</button><button class="small-button" type="button" data-media>音视频</button><input type="file" data-photo-input accept="image/jpeg,image/png,image/webp,image/heic" multiple hidden><input type="file" data-media-input accept="audio/*,video/*" multiple hidden>';
 section.querySelector('.upload').after(actions);
 const dialog=document.createElement('dialog');dialog.className='photo-book-dialog';dialog.innerHTML='<header><h3>整理照片</h3><button type="button" class="small-button" data-close>关闭</button></header><input class="photo-book-name" aria-label="曲谱名称" placeholder="曲谱名称"><ol class="photo-pages"></ol><footer><button type="button" class="small-button" data-add>继续添加</button><button type="button" class="primary" data-submit>开始识谱</button></footer><p role="status"></p>';document.body.append(dialog);
 const photoInput=actions.querySelector('[data-photo-input]'),mediaInput=actions.querySelector('[data-media-input]');let photos=[],working=false;
 function draw(){const list=dialog.querySelector('ol');list.replaceChildren();photos.forEach((photo,index)=>{const row=document.createElement('li'),image=document.createElement('img'),label=document.createElement('span');image.src=photo.url;image.alt=`第 ${index+1} 页`;label.textContent=`${index+1}. ${photo.file.name}`;row.append(image,label);
  for(const [text,delta] of [['上移',-1],['下移',1],['移除',0]]){const button=document.createElement('button');button.type='button';button.textContent=text;button.className='small-button';button.disabled=working||(delta<0&&index===0)||(delta>0&&index===photos.length-1);button.onclick=()=>{if(delta)[photos[index],photos[index+delta]]=[photos[index+delta],photos[index]];else{URL.revokeObjectURL(photos[index].url);photos.splice(index,1);}draw();};row.append(button);}list.append(row);});dialog.querySelector('[data-submit]').disabled=working||!photos.length;}
 actions.querySelector('[data-photos]').onclick=()=>{dialog.showModal();};actions.querySelector('[data-media]').onclick=()=>mediaInput.click();dialog.querySelector('[data-add]').onclick=()=>photoInput.click();dialog.querySelector('[data-close]').onclick=()=>dialog.close();
 photoInput.onchange=()=>{if(working)return;for(const file of photoInput.files)photos.push({file,url:URL.createObjectURL(file)});photoInput.value='';if(!dialog.open)dialog.showModal();draw();};
 async function upload(file,path,id){if(file.size>(path==='/api/media'?200:20)*1024*1024)throw Error('文件过大');return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest(),started=performance.now();let realProgress=1,pulse=0;
  const tick=()=>{const elapsed=performance.now()-started;const ceiling=realProgress>2?Math.min(88,realProgress+4):Math.min(12,2+elapsed/900);pulse=ceiling;reportTask(id,{progress:pulse,detail:realProgress>2?`正在上传 ${file.name}`:`正在连接上传服务 · ${file.name}`});};
  tick();const timer=setInterval(tick,420);const finish=()=>clearInterval(timer);xhr.open('POST',path);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-Score-Name',encodeURIComponent(file.name));xhr.setRequestHeader('X-Media-Type',file.type||'');xhr.upload.onloadstart=()=>reportTask(id,{progress:2,detail:`开始上传 · ${file.name}`});xhr.upload.onprogress=e=>{realProgress=e.lengthComputable?Math.max(3,e.loaded/e.total*86):Math.max(realProgress,3);reportTask(id,{progress:realProgress,detail:e.lengthComputable?`上传 ${Math.round(e.loaded/e.total*100)}% · ${file.name}`:`正在上传 · ${file.name}`});};xhr.onerror=()=>{finish();reject(Error('上传连接中断'));};xhr.onload=()=>{finish();let result;try{result=JSON.parse(xhr.responseText);}catch{return reject(Error(xhr.status===404?'音视频服务尚未启用，请重启本机服务后重试':'服务器返回了无法读取的结果'));}if(xhr.status>=300)return reject(Error(result.error||'上传失败'));reportTask(id,{progress:94,detail:'上传完成，正在加入转录队列'});resolve(result);};xhr.send(file);});}
 let mediaQueue=Promise.resolve();mediaInput.onchange=()=>{const files=[...mediaInput.files];mediaInput.value='';if(!files.length)return;showTasks();for(const file of files){const id=taskId('media');reportTask(id,{label:file.name,kind:'transcription',status:'queued',progress:0,detail:'等待上传'});mediaQueue=mediaQueue.then(async()=>{try{reportTask(id,{status:'running',progress:1,detail:'准备上传'});const result=await upload(file,'/api/media',id);reportTask(id,{status:'complete',progress:100,digest:result.id,detail:'上传完成，已加入转录队列'});await onUploaded({...result,media:true});}catch(error){reportTask(id,{status:'failed',detail:error.message});}});}};
 dialog.querySelector('[data-submit]').onclick=async()=>{if(working||!photos.length)return;if(photos.length>40){dialog.querySelector('[role=status]').textContent='每本曲谱最多 40 张照片';return;}working=true;dialog.querySelector('[data-add]').disabled=true;draw();const id=taskId('photos'),name=dialog.querySelector('.photo-book-name').value.trim()||photos[0].file.name.replace(/\.[^.]+$/,'');reportTask(id,{label:name,status:'running',progress:0});
  try{const pages=[];for(const [index,photo] of photos.entries()){dialog.querySelector('[role=status]').textContent=`上传 ${index+1} / ${photos.length}`;pages.push((await upload(photo.file,'/api/photos',id)).id);}const response=await fetch('/api/photo-books',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pages,name})});const result=await response.json();if(!response.ok)throw Error(result.error);reportTask(id,{status:'complete',progress:100,digest:result.id,detail:'照片已提交'});photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[];dialog.close();showTasks();await onUploaded({...result,media:true});}
  catch(error){dialog.querySelector('[role=status]').textContent=error.message;reportTask(id,{status:'failed',detail:error.message});}finally{working=false;dialog.querySelector('[data-add]').disabled=false;draw();}
 };draw();
}
